221	func TestPackageNeverStartsAProcess(t *testing.T) {
222		entries, err := os.ReadDir(".")
223		if err != nil {
224			t.Fatal(err)
225		}
226		fset := token.NewFileSet()
227		files := 0
228		for _, e := range entries {
229			if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
230				continue
231			}
232			src, err := os.ReadFile(e.Name())
233			if err != nil {
234				t.Fatal(err)
235			}
236			files++
237			offences, err := guardSource(fset, e.Name(), src)
238			if err != nil {
239				t.Errorf("%s: %v", e.Name(), err)
240				continue
241			}
242			for _, o := range offences {
243				t.Error(o + ": the trace must not start or exec a process")
244			}
245		}
246		if files == 0 {
247			t.Error("the scan saw no Go file: the guard would pass vacuously")
248		}
