53	// socket symbols the engine needs (Recvmsg, Setsockopt...) stay allowed.
54	var bannedSymbols = map[string]map[string]bool{
55		"os": {"StartProcess": true},
56		"syscall": {
57			"StartProcess": true, "ForkExec": true, "Exec": true,
58			"Syscall": true, "Syscall6": true, "RawSyscall": true, "RawSyscall6": true,
