78	// isStringLit reports whether e is a string literal and returns its value.
79	func isStringLit(e ast.Expr) (string, bool) {
80		lit, ok := e.(*ast.BasicLit)
81		if !ok || lit.Kind != token.STRING {
82			return "", false
83		}
84		v, err := strconv.Unquote(lit.Value)
85		return v, err == nil
86	}
