88	// winCallOffence checks the two Windows loading rules on a call in a file
89	// that imports x/sys/windows: NewLazySystemDLL takes the literal "iphlpapi.dll"
90	// only, and NewProc takes a literal from winProcs only. It returns a message
91	// or "". One call is one offence at most.
92	func winCallOffence(fset *token.FileSet, call *ast.CallExpr, winNames map[string]bool) string {
93		sel, ok := call.Fun.(*ast.SelectorExpr)
94		if !ok || len(call.Args) != 1 {
95			return ""
96		}
97		lit, isLit := isStringLit(call.Args[0])
98		switch sel.Sel.Name {
99		case "NewLazySystemDLL":
100			id, ok := sel.X.(*ast.Ident)
101			if !ok || !winNames[id.Name] {
102				return ""
103			}
104			if !isLit || lit != winDLL {
105				return fmt.Sprintf("%s: NewLazySystemDLL may load only the literal %q", fset.Position(call.Pos()), winDLL)
106			}
107		case "NewProc":
108			if !isLit || !winProcs[lit] {
109				return fmt.Sprintf("%s: NewProc may resolve only the ICMP echo entry points by literal name", fset.Position(call.Pos()))
110			}
111		}
112		return ""
113	}
