115	// guardSource returns one message per offence in src ("name:line: ...").
116	func guardSource(fset *token.FileSet, name string, src any) ([]string, error) {
117		file, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
118		if err != nil {
119			return nil, err
120		}
121		var out []string
122		local := map[string]string{}  // local package name -> import path
123		winNames := map[string]bool{} // local names of x/sys/windows
124		importsWin := false
125		for _, imp := range file.Imports {
126			path, _ := strconv.Unquote(imp.Path.Value)
127			if bannedImports[path] {
128				out = append(out, fmt.Sprintf("%s: import of %s", fset.Position(imp.Pos()), path))
129			}
130			if imp.Name != nil && imp.Name.Name == "." && dotWatched[path] {
131				out = append(out, fmt.Sprintf("%s: dot-import of %s", fset.Position(imp.Pos()), path))
132			}
133			if path == winPath {
134				importsWin = true
135			}
136			if _, watched := bannedSymbols[path]; !watched {
137				continue
138			}
139			n := path[strings.LastIndex(path, "/")+1:]
140			if imp.Name != nil {
141				n = imp.Name.Name
142			}
143			local[n] = path
144			if path == winPath {
145				winNames[n] = true
146			}
147		}
148		ast.Inspect(file, func(n ast.Node) bool {
149			if call, ok := n.(*ast.CallExpr); ok && importsWin {
150				if msg := winCallOffence(fset, call, winNames); msg != "" {
151					out = append(out, msg)
152				}
153				return true
154			}
155			sel, ok := n.(*ast.SelectorExpr)
156			if !ok {
157				return true
158			}
