160			if !ok {
161				return true
162			}
163			if path, ok := local[id.Name]; ok && bannedSymbols[path][sel.Sel.Name] {
164				out = append(out, fmt.Sprintf("%s: use of %s.%s", fset.Position(sel.Pos()), id.Name, sel.Sel.Name))
165			}
166			return true
167		})
